export default function CropIllustration({ crop, className = '' }: { crop: CropArt; className?: string }) {
  return <div className={`aspect-[4/3] overflow-hidden rounded-xl bg-white ${className}`}>
    <img src={PHOTOS[crop].src} alt="" aria-hidden="true" width={500} height={375} decoding="async" className="h-full w-full object-contain" />
  </div>;
}

export function HarvestBannerArt() {
  return <img src={PHOTOS.hero.src} alt="" aria-hidden="true" width={500} height={333} className="h-full w-full object-cover object-center" />;
}

export function PhotoCredits() {
  return <details className="mx-4 mb-4 text-[10px] leading-relaxed text-stone-400 sm:mx-8">
    <summary className="w-fit cursor-pointer rounded px-1 py-1 transition hover:text-emerald-800 focus-visible:outline-2 focus-visible:outline-emerald-700">Photo credits</summary>
    <ul className="mt-2 grid gap-x-5 gap-y-1 rounded-xl bg-stone-50 p-3 sm:grid-cols-2">
      {Object.entries(PHOTOS).map(([key, photo]) => <li key={key}>
        <a href={photo.source} target="_blank" rel="noreferrer" className="underline underline-offset-2 hover:text-emerald-800">{photo.title}</a>
        {' — '}{photo.artist}{' · '}
        {photo.licenseUrl ? <a href={photo.licenseUrl} target="_blank" rel="noreferrer" className="underline underline-offset-2 hover:text-emerald-800">{photo.license}</a> : photo.license}
        {' · Thumbnail; no retouching.'}
      </li>)}
    </ul>
  </details>;
}
